    def _add_certificate_soam(self):
        """Adds certificate on the BTS to authenticate secgw using SOAM"""
        default_cert_file = self._get_delta_commission_file(self.DEFAULT_CERT_FILE)
        self.ute_admin.setup_admin(bts_host="192.168.255.129", bts_port=443, use_ssl=True, alias='ipsec_admin')
        self.ute_admin.install_certificate(default_cert_file, "BtsTrustChain", "P12", 'nsnCERT', alias='ipsec_admin')
        self.ute_admin.teardown_admin(alias='ipsec_admin')

