    def _create_required_delta_commissioning_file(self):
        return self._create_required_delta_commissioning_file_soam()

    def _create_required_delta_commissioning_file_soam(self):
        self._get_latest_scfc_file_soam()
        file_name = "/tmp/192.168.255.129_scf.xml"
        return file_name

    def _create_required_delta_commissioning_file_sem(self):
        matched_items_file = self._create_security_policies_list_file()
        header_content_file = self._get_delta_commission_file(self.HEADER_CONTENT_FILE)
        footer_content_file = self._get_delta_commission_file(self.FOOTER_CONTENT_FILE)
        filenames = [header_content_file, matched_items_file, footer_content_file]
        delta_commissioning_file = self._merge_files(filenames)
        return delta_commissioning_file

    def _create_security_policies_list_file(self):
        return self._create_security_policies_list_file_soam()

    def _create_security_policies_list_file_soam(self):
        namespaces = {'r': 'raml21.xsd'}
        xpath = "/r:raml/r:cmData/r:managedObject[@class='NOKLTE:IPSECC']/r:list[@name='securityPolicies']/r:item"
        matched_items = self._fetch_required_elements(xpath, namespaces)
        matched_items_file = self._push_matched_items_into_a_file(matched_items)
        return matched_items_file

    def _create_security_policies_list_file_sem(self):
        namespaces = {'r': 'raml21.xsd'}
        xpath = "/r:raml/r:cmData/r:managedObject[@class='NOKLTE:IPSECC']/r:list[@name='securityPolicies']/r:item"
        matched_items = self._fetch_required_elements(xpath, namespaces)
        matched_items_file = self._push_matched_items_into_a_file(matched_items)
        return matched_items_file

    def _fetch_required_elements(self, xpath, namespaces):
        self._get_latest_scfc_file()
        root = etree.parse('/tmp/latest_scfc_file.xml')
        matched_items = root.xpath(xpath, namespaces=namespaces)
        return matched_items

    def _get_latest_scfc_file(self):
        self._get_latest_scfc_file_soam()

    def _get_latest_scfc_file_soam(self):
        self.ute_admin.setup_admin(bts_host="192.168.255.129", bts_port=443, use_ssl=True, alias='backup')
        self.ute_admin.collect_scf('/tmp/192.168.255.129_scf.xml', alias='backup')
        self.ute_admin.teardown_admin(alias='backup')

    def _push_matched_items_into_a_file(self, matched_items):
        fd, matched_items_file = tempfile.mkstemp()
        opened_file = open(matched_items_file, "a")
        for i in range(len(matched_items)):
            print(etree.tostring(matched_items[i], pretty_print=True), opened_file)
            # print >> opened_file, etree.tostring(matched_items[i], pretty_print=True)
        opened_file.close()
        return matched_items_file

    def _merge_files(self, filenames):
        fd, delta_commissioning_file = tempfile.mkstemp()
        with open(delta_commissioning_file, 'w') as outfile:
            for fname in filenames:
                with open(fname) as infile:
                    outfile.write(infile.read())
        return delta_commissioning_file

    def _edit_all_policies_parameters(self, file_to_edit, policy_numbers, **parameters):
        root_element = etree.parse(file_to_edit)
        namespaces = {'r': 'raml21.xsd'}
        for policy_number in policy_numbers:
            self._edit_policy_parameters_soam(namespaces, parameters, policy_number, root_element)
        self._save_edited_xml_file(file_to_edit, root_element)

    def _edit_policy_parameters_sem(self, namespaces, parameters, policy_number, root_element):
        policy_index_in_xml = self._get_policy_index_in_xml(policy_number)
        if policy_index_in_xml is not None:
            xpath = "/r:raml/r:cmData/r:managedObject[@class='NOKLTE:IPSECC']/r:list[@name='securityPolicies']/r:item[{}]".format(
                policy_index_in_xml)
            matched_elements = root_element.xpath(xpath, namespaces=namespaces)
            self._replace_parameter_values(matched_elements, parameters)

    def _edit_policy_parameters_soam(self, namespaces, parameters, policy_number, root_element):
        policy_index_in_xml = self._get_policy_index_in_xml(policy_number)
        if policy_index_in_xml is not None:
            xpath = "/r:raml/r:cmData/r:managedObject[@distName='MRBTS-1/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/IKEP-{}']".format(
                policy_index_in_xml)
            matched_elements = root_element.xpath(xpath, namespaces=namespaces)
            self._replace_parameter_values(matched_elements, parameters)
            xpath = "/r:raml/r:cmData/r:managedObject[@distName='MRBTS-1/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/SECPOL-{}']".format(
                policy_index_in_xml)
            matched_elements = root_element.xpath(xpath, namespaces=namespaces)
            self._replace_parameter_values(matched_elements, parameters)
            xpath = "/r:raml/r:cmData/r:managedObject[@distName='MRBTS-1/TNLSVC-1/TNL-1/IPAPP-1/IPSECC-1/IPSECP-{}']".format(
                policy_index_in_xml)
            matched_elements = root_element.xpath(xpath, namespaces=namespaces)
            self._replace_parameter_values(matched_elements, parameters)
        else:
            raise Exception('Policy numbers are not correct')

    def _get_policy_index_in_xml(self, policy_number):
        policy_number_index_dict = POLICY_NUMBER_INDEX_DICT
        try:
            return policy_number_index_dict[policy_number]
        except KeyError:
            return None

    def _replace_parameter_values(self, matched_elements, parameters):
        for parameter_name in parameters.keys():
            for element in matched_elements[0].iter():
                self._replace_xml_value(element, parameter_name, parameters[parameter_name])

    def _replace_xml_value(self, element, parameter_name, parameter_val):
        if len(element.items()) > 0 and element.items()[0][1] == parameter_name:
            element.text = parameter_val

    def _save_edited_xml_file(self, file_to_edit, root_element):
        with open(file_to_edit, 'w') as file_handle:
            file_handle.write(etree.tostring(root_element, pretty_print=True))

    def _edit_vlanids_in_commission_file(self, vlan_ids, template_file):
        template = self._get_template(template_file)
        if len(vlan_ids) == 4:
            content = template.render(vlan_id_1=vlan_ids[0], vlan_id_2=vlan_ids[1], vlan_id_3=vlan_ids[2],
                                      vlan_id_4=vlan_ids[3])
        elif len(vlan_ids) == 6:
            content = template.render(vlan_id_1=vlan_ids[0], vlan_id_2=vlan_ids[1], vlan_id_3=vlan_ids[2],
                                      vlan_id_4=vlan_ids[3],
                                      vlan_id_5=vlan_ids[4], vlan_id_6=vlan_ids[5])
        temp_commissioning_file = self._write_temp_file(content)
        return temp_commissioning_file

    def _edit_enbs1ips_in_template_file(self, enbs1ip, template_file):
        template = self._get_template(template_file)
        content = template.render(enb_s1_ip=enbs1ip)
        temp_commissioning_file = self._write_temp_file(content)
        return temp_commissioning_file

    def _get_template(self, template_name):
        env = Environment(loader=PackageLoader(__name__, 'resources'))
        template = env.get_template(template_name)
        return template

    def _write_temp_file(self, content):
        fd, file_name = tempfile.mkstemp()
        with open(file_name, 'w') as file_handle:
            file_handle.write(content)
        os.close(fd)
        return file_name

    def _perform_delta_commissioning_and_delete_file_afterwards(self, edited_commissioning_file, is_reset_required):
        with self._delete_file(edited_commissioning_file):
                self.perform_delta_commissioning_soam(edited_commissioning_file)

    def _perform_full_commissioning_and_delete_file_afterwards(self, edited_commissioning_file, is_reset_required):
        with self._delete_file(edited_commissioning_file):
                self.perform_full_commissioning_soam(edited_commissioning_file)

    def perform_delta_commissioning_soam(self, delta_commission_file):
        """Performs delta commissining in SOAM"""
        if not os.path.exists(delta_commission_file):
            delta_commission_file = self._get_delta_commission_file(delta_commission_file)
        self.ute_admin.setup_admin(bts_host="192.168.255.129", bts_port=443, use_ssl=True, alias='ipsec_admin')
        self.json_conversion.convert_delta_xml_to_json(delta_commission_file, "/tmp/abc.xml")
        self.ute_admin.perform_delta_recommissioning("/tmp/abc.xml", True, timeout=1200, alias='ipsec_admin')
        sleep(190)
        self.ute_admin.teardown_admin(alias='ipsec_admin')

    def perform_full_commissioning_soam(self, full_commission_file):
        """Performs Full commissining in SOAM"""
        if not os.path.exists(full_commission_file):
            full_commission_file = self._get_delta_commission_file(full_commission_file)
        self.ute_admin.setup_admin(bts_host="192.168.255.129", bts_port=443, use_ssl=True, alias='full_commissioning')
        self.ute_admin.perform_commissioning("1", full_commission_file, True, timeout=1200, alias='full_commissioning')
        self.ute_admin.teardown_admin(alias='full_commissioning')
        sleep(180)

    @contextmanager
    def _delete_file(self, file_path):
        try:
            yield
        finally:
            os.remove(file_path)

    def _get_delta_commission_file(self, file_name):
        here = os.path.dirname(__file__)
        file_path = os.path.join(here, 'resources/{}'.format(file_name))
        return file_path
